package com.miniforce.service;
import com.miniforce.dto.*; import com.miniforce.dto.AuthDtos.*; import com.miniforce.exception.*; import com.miniforce.model.*; import com.miniforce.repository.UserRepository; import com.miniforce.security.JwtService; import org.springframework.security.crypto.password.PasswordEncoder; import org.springframework.stereotype.Service; import org.springframework.transaction.annotation.Transactional;
@Service public class AuthService {
 private final UserRepository users; private final PasswordEncoder encoder; private final JwtService jwt; public AuthService(UserRepository u,PasswordEncoder e,JwtService j){users=u;encoder=e;jwt=j;}
 @Transactional public AuthResponse register(RegisterRequest r){String username=r.username().trim().toLowerCase(),email=r.email().trim().toLowerCase(); if(users.existsByUsernameIgnoreCase(username))throw new ConflictException("Username is already taken");if(users.existsByEmailIgnoreCase(email))throw new ConflictException("Email is already registered");User u=new User();u.setFullName(r.fullName().trim());u.setUsername(username);u.setEmail(email);u.setPasswordHash(encoder.encode(r.password()));users.save(u);return new AuthResponse(jwt.generate(u),UserResponse.from(u));}
 public AuthResponse login(LoginRequest r){String identity=r.identity().trim();User u=identity.contains("@")?users.findByEmailIgnoreCase(identity).orElseThrow(()->new com.miniforce.exception.UnauthorizedException("Invalid email/username or password")):users.findByUsernameIgnoreCase(identity).orElseThrow(()->new com.miniforce.exception.UnauthorizedException("Invalid email/username or password"));if(!encoder.matches(r.password(),u.getPasswordHash()))throw new com.miniforce.exception.UnauthorizedException("Invalid email/username or password");return new AuthResponse(jwt.generate(u),UserResponse.from(u));}
 public UserResponse me(User u){return UserResponse.from(u);}
}
